//! Generated by `undra dev`: serves the app core over a WebSocket for the platform runtimes'
//! `remote` transport.
//!
//! ```text
//! undra-dev-runner [ADDR] [--log-level N] [--print-schema]
//! ```
//!
//! It prints one machine-readable line, `UNDRA-DEV ready <ws-url> <schema-hash>`, on stdout and
//! keeps running until its stdin closes (so it cannot outlive `undra dev`). Log records, the dev
//! records of docs/SPEC.md 5.10 included, go to stderr.
#![forbid(unsafe_code)]

use std::io::{Read, Write};
use std::time::{SystemTime, UNIX_EPOCH};

use undra_runtime::{Runtime, RuntimeConfig};
use undra_transport::{Server, ServerConfig};

// Links the core, whose `#[undra::api]` items register themselves with the runtime at load time.
extern crate app_core;

const LEVELS: [&str; 6] = ["TRACE", "DEBUG", "INFO ", "WARN ", "ERROR", "FATAL"];

/// Prints one log record: `12:03:44.123 DEBUG undra::runtime: txn 7: 2 dirty`.
fn print_log(level: u8, target: &str, message: &str) {
    let since_midnight = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_or(0, |d| d.as_millis() % 86_400_000);
    let (h, m, s, ms) = (
        since_midnight / 3_600_000,
        since_midnight / 60_000 % 60,
        since_midnight / 1000 % 60,
        since_midnight % 1000,
    );
    let name = LEVELS.get(usize::from(level)).copied().unwrap_or("?????");
    let _ = writeln!(
        std::io::stderr().lock(),
        "{h:02}:{m:02}:{s:02}.{ms:03} {name} {target}: {message}"
    );
}

// @ports:begin
use std::sync::Arc;

/// The native `Clock` (SPEC 8): a dev core runs on your computer, so it asks your computer's
/// clock. Synchronous ports cannot be answered by a remote client, which is why these are Rust
/// bindings.
struct NativeClock(std::time::Instant);

impl undra_ports::Clock for NativeClock {
    fn now_ms(&self) -> i64 {
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map_or(0, |d| i64::try_from(d.as_millis()).unwrap_or(i64::MAX))
    }

    fn monotonic_ns(&self) -> u64 {
        u64::try_from(self.0.elapsed().as_nanos()).unwrap_or(u64::MAX)
    }
}

/// The native `Rng`: the operating system's random source where there is one.
struct NativeRng;

impl undra_ports::Rng for NativeRng {
    fn fill(&self, len: u32) -> undra_runtime::undra_wire::Bytes {
        let mut bytes = vec![0_u8; usize::try_from(len.min(1 << 24)).unwrap_or(0)];
        let from_os = std::fs::File::open("/dev/urandom").and_then(|mut f| f.read_exact(&mut bytes));
        if from_os.is_err() {
            use std::hash::{BuildHasher, Hasher};
            let state = std::collections::hash_map::RandomState::new();
            for (i, byte) in bytes.iter_mut().enumerate() {
                let mut hasher = state.build_hasher();
                hasher.write_usize(i);
                *byte = hasher.finish().to_le_bytes()[0];
            }
        }
        undra_runtime::undra_wire::Bytes(bytes)
    }
}

/// The native `Log`: records go to the terminal next to the runtime's own.
struct NativeLog;

impl undra_ports::Log for NativeLog {
    fn log(&self, level: u8, target: String, message: String) {
        print_log(level, &target, &message);
    }
}

fn bind_native_ports(runtime: &Arc<Runtime>) {
    use undra_runtime::Port;
    runtime.bind_dyn_port::<dyn undra_ports::Clock>(
        <dyn undra_ports::Clock as Port>::PORT_ID,
        Arc::new(NativeClock(std::time::Instant::now())),
    );
    runtime.bind_dyn_port::<dyn undra_ports::Rng>(<dyn undra_ports::Rng as Port>::PORT_ID, Arc::new(NativeRng));
    runtime.bind_dyn_port::<dyn undra_ports::Log>(<dyn undra_ports::Log as Port>::PORT_ID, Arc::new(NativeLog));
}
// @ports:end

fn main() {
    let mut addr = "127.0.0.1:7443".to_owned();
    let mut log_level = 1_u8;
    let mut print_schema = false;
    let mut args = std::env::args().skip(1);
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--print-schema" => print_schema = true,
            "--log-level" => {
                log_level = args.next().and_then(|v| v.parse().ok()).unwrap_or(log_level);
            }
            other => addr = other.to_owned(),
        }
    }

    if print_schema {
        // The full schema, doc comments included: what the C ABI's `undra_schema_json` returns
        // too (compact there), kept so the two can be compared.
        println!("{}", undra_runtime::undra_meta::collect_schema("@@CORE_PACKAGE_RAW@@").to_json_pretty());
        return;
    }

    // A client that drops (a phone that slept, an app the OS suspended) finds its objects again
    // for ten minutes if it comes back with its session token (ADR-051).
    let config = ServerConfig {
        resume_grace: std::time::Duration::from_secs(600),
        ..ServerConfig::default()
    };
    let server = match Server::start(addr.as_str(), config, |host| {
        host.set_log_sink(print_log);
        let runtime = Runtime::new(
            RuntimeConfig {
                platform: "rust".to_owned(),
                mode: "dev".to_owned(),
                log_level,
                ..RuntimeConfig::default()
            },
            host,
        )?;
        // @ports:begin
        bind_native_ports(&runtime);
        // @ports:end
        Ok(runtime)
    }) {
        Ok(server) => server,
        Err(e) => {
            eprintln!("undra-dev-runner: cannot serve on {addr}: {e}");
            std::process::exit(2);
        }
    };

    println!("UNDRA-DEV ready {} {:#018x}", server.url(), server.runtime().schema_hash());
    let _ = std::io::stdout().flush();

    // Serve until stdin closes: `undra dev` holds the other end, so this process ends when it does.
    let mut sink = Vec::new();
    let _ = std::io::stdin().read_to_end(&mut sink);
    server.shutdown();
    server.runtime().shutdown();
}
